2	
3	import (
4		"context"
5		"encoding/json"
6		"fmt"
7		"slices"
8		"strings"
9	)
10	
11	// Op is what a run of the bench is about to do; it decides which checks the
12	// preflight makes.
13	type Op int
14	
15	const (
16		OpUp Op = iota
17		OpProvision
18		OpDown
19		OpStatus
20		// OpSeed is appended after OpStatus: no earlier value moves.
21		OpSeed
22	)
23	
24	// PreflightResult is what a successful preflight learned about the cluster.
25	type PreflightResult struct {
26		// NamespaceExists is true when the bench namespace is there.
27		NamespaceExists bool
28		// NamespaceOurs is true when it carries our managed-by label.
29		NamespaceOurs bool
30		// NodeIP is the InternalIP of the first node that reports one; empty when
31		// none does, which is not an error (the other hosts still work). It is not
32		// read for OpDown.
33		NodeIP string
34	}
35	
36	const (
37		// managedByLabel and managedByValue are the label 00-namespace.yaml.tmpl
38		// puts on the namespace; down deletes a namespace only when it carries it.
39		managedByLabel = "app.kubernetes.io/managed-by"
40		managedByValue = "devdesk-nexus-bench"
41	
42		// nexusServiceName is the Service 30-service.yaml.tmpl creates.
43		nexusServiceName = "nexus"
44	
45		// requestTimeout bounds every call that reaches the API server.
46		requestTimeout = "--request-timeout=10s"
47	)
48	
49	// permissionScope says where a can-i question applies.
50	type permissionScope int
51	
52	const (
53		scopeCluster   permissionScope = iota // no flag: cluster-scoped resources
54		scopeNamespace                        // -n <namespace>
55		scopeAll                              // -A
56	)
57	
58	// permission is one "kubectl auth can-i" question the preflight asks.
59	type permission struct {
60		verb, resource string
61		// subresource is asked as --subresource=<sub>: kubectl reads "pods/exec" as
62		// the object "exec" of the pods, not as the exec subresource.
63		subresource string
64		scope       permissionScope
65	}
66	
67	// name is the resource as a message shows it: "pods/exec".
68	func (perm permission) name() string {
69		if perm.subresource == "" {
70			return perm.resource
71		}
72		return perm.resource + "/" + perm.subresource
73	}
74	
75	// permissionsByOp is the list F2 of the plan: what each operation needs. An
76	// operation absent from the map (status) writes nothing and asks nothing.
77	var permissionsByOp = map[Op][]permission{
78		OpUp: {
79			{"create", "namespaces", "", scopeCluster},
80			{"create", "persistentvolumeclaims", "", scopeNamespace},
81			{"create", "services", "", scopeNamespace},
82			{"create", "deployments", "", scopeNamespace},
83			{"create", "pods", "exec", scopeNamespace},
84			{"list", "services", "", scopeAll},
85			// Server-side apply is a PATCH, also on a second run (the namespace
86			// included), and Deploy reads the pods and the claims of the namespace
87			// while it waits.
88			{"patch", "namespaces", "", scopeCluster},
89			{"patch", "deployments", "", scopeNamespace},
90			{"patch", "services", "", scopeNamespace},
91			{"patch", "persistentvolumeclaims", "", scopeNamespace},
92			{"get", "pods", "", scopeNamespace},
93			{"list", "pods", "", scopeNamespace},
94			{"get", "persistentvolumeclaims", "", scopeNamespace},
95			{"list", "persistentvolumeclaims", "", scopeNamespace},
96			// The upstream: EnsureUpstream scales it, and the seed that follows up
97			// reaches it through a port-forward, which reads the Service first. Asked
98			// last, so the fourteen above stay where they were.
99			{"patch", "deployments", "scale", scopeNamespace},
100			{"create", "pods", "portforward", scopeNamespace},
101			{"get", "services", "", scopeNamespace},
102		},
103		// Provision waits for the Deployment and reads the pods before it execs.
104		OpProvision: {
105			{"create", "pods", "exec", scopeNamespace},
106			{"get", "deployments", "", scopeNamespace},
107			{"list", "pods", "", scopeNamespace},
108		},
109		OpDown: {{"delete", "namespaces", "", scopeCluster}},
110		// Seed reads the Deployment and the pods of the upstream, scales it back
111		// when it is cut, and reaches it through a port-forward, which gets the
112		// Service, then the pod it picks, before it opens the tunnel. EnsureUpstream
113		// reads the claim on every turn of its wait, so the two claim questions come
114		// before the first write.
115		OpSeed: {
116			{"get", "deployments", "", scopeNamespace},
117			{"list", "pods", "", scopeNamespace},
118			{"get", "pods", "", scopeNamespace},
119			{"get", "services", "", scopeNamespace},
120			{"get", "persistentvolumeclaims", "", scopeNamespace},
121			{"list", "persistentvolumeclaims", "", scopeNamespace},
122			{"create", "pods", "portforward", scopeNamespace},
123			{"patch", "deployments", "scale", scopeNamespace},
124		},
125	}
126	
127	// RunPreflight checks, with read-only kubectl calls, that op can go ahead, and
128	// returns what it learned. Nothing is written to the cluster, whatever the
129	// outcome: a failure here means no write was ever issued. The checks run in a
130	// fixed order and stop at the first failure, so nothing is asked of a cluster
131	// the context does not reach:
132	//
133	//  1. the parameters (no call at all)
134	//  2. the context is in the kubeconfig
135	//  3. the API server answers /readyz
136	//  4. the can-i questions of the operation
137	//  5. the namespace: absent, ours, or foreign
138	//  6. up only: no other Service holds one of our NodePorts
139	//  7. all but down and seed: the InternalIP of the node
140	//
141	// Every failure is a *BenchError.
142	func RunPreflight(ctx context.Context, r Runner, p Params, op Op) (PreflightResult, error) {
143		var res PreflightResult
144		if err := p.Validate(); err != nil {
145			return res, err
146		}
147		pf := preflight{r: r, p: p}
148		if err := pf.checkContext(ctx); err != nil {
149			return res, err
150		}
151		if err := pf.checkReachable(ctx); err != nil {
152			return res, err
153		}
154		for _, perm := range permissionsByOp[op] {
155			if err := pf.checkPermission(ctx, perm); err != nil {
156				return res, err
157			}
158		}
159		res, err := pf.checkNamespace(ctx, op)
160		if err != nil {
161			return res, err
162		}
163		if op == OpUp {
164			if err := pf.checkNodePorts(ctx); err != nil {
165				return res, err
166			}
167		}
168		// The seed reaches the registries through a port-forward on the loopback: it
169		// has no use for the node address and no can-i question covers get nodes.
170		if op != OpDown && op != OpSeed {
