219		args := []string{"config", "get-contexts", "-o", "name"}
220		out, errOut, err := pf.local(ctx, args...)
221		if err != nil {
222			return pf.failure("list the kubeconfig contexts", args, errOut, err)
223		}
224		for _, line := range strings.Split(out, "\n") {
225			if strings.TrimSpace(line) == pf.p.Context {
226				return nil
227			}
228		}
229		return &BenchError{
230			Kind:  ContextNotFound,
231			Cause: fmt.Sprintf("no kubeconfig context is named %q", pf.p.Context),
232			Check: "kubectl config get-contexts -o name, then set NEXUS_BENCH_CONTEXT to one of them",
233		}
234	}
