236	func (pf preflight) checkReachable(ctx context.Context) error {
237		args := []string{"get", "--raw", "/readyz"}
238		_, errOut, err := pf.remote(ctx, args...)
239		if err == nil {
240			return nil
241		}
242		// A refusal (an expired token, a 403) is not an absent cluster: say so.
243		// Anything else, classified or not, means the server did not answer.
244		if classifyKubectl(errOut) == Forbidden {
245			return pf.failure("reach the API server", args, errOut, err)
246		}
247		return &BenchError{
248			Kind:  ClusterUnreachable,
249			Cause: fmt.Sprintf("the API server of context %q does not answer /readyz", pf.p.Context),
250			Check: pf.command(args...),
251			Err:   err,
252		}
253	}
