255	// checkPermission asks "kubectl auth can-i". A "no" arrives on stdout with a
256	// non-zero exit, so the answer is read before the error.
257	func (pf preflight) checkPermission(ctx context.Context, perm permission) error {
258		args := []string{"auth", "can-i", perm.verb, perm.resource}
259		if perm.subresource != "" {
260			args = append(args, "--subresource="+perm.subresource)
261		}
262		where := "cluster-wide"
263		switch perm.scope {
264		case scopeNamespace:
265			args = append(args, "-n", pf.p.Namespace)
266			where = fmt.Sprintf("in namespace %q", pf.p.Namespace)
267		case scopeAll:
268			args = append(args, "-A")
269			where = "in all namespaces"
270		}
271		out, errOut, err := pf.remote(ctx, args...)
272		answer := strings.TrimSpace(out)
273		switch {
274		case strings.HasPrefix(answer, "no"):
275			return &BenchError{
276				Kind:  Forbidden,
277				Cause: fmt.Sprintf("the current user is not allowed to %s %s %s", perm.verb, perm.name(), where),
278				Check: pf.command(args...),
279				Err:   err,
280			}
281		case err == nil && strings.HasPrefix(answer, "yes"):
282			return nil
283		}
284		return pf.failure(fmt.Sprintf("check the permission to %s %s", perm.verb, perm.name()), args, errOut, err)
285	}
